-- GENERATED by `wfj generate` from data/quest/quest-0086.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [86574] = { "Rifornimenti per ⟦Stonetalon=Petrartiglio⟧", "Raccogli $N1 Stonetalon Supplies dalle Pridewing Wyvern e consegnali alla locandiera Faralia.", "<Il povero corpo porta i segni di molti colpi delle viverne Pridewing. Lo zaino lì accanto è sgualcito e abbandonato, svuotato del contenuto; solo un piccolo biglietto stretto nella mano del corriere indica cosa sia andato perduto: un carico destinato alla locandiera Faralia, al ⟦Stonetalon Peak=Picco di Petrartiglio⟧.>\n\n<Probabilmente le viverne hanno portato via i fagotti di provviste per imbottirci i nidi.>", "Spero che quella spedizione arrivi presto...", "Hai trovato la spedizione smarrita?\n\nOh, non avevo idea che la corriera non fosse arrivata. È... una situazione tragica...\n\nUserò questi rifornimenti nel modo migliore, perché la sua perdita non sia vana.", 0x91254c7f, 0x88cf623c, 0x25ddc985, 0x9648fffa, 0x0b518b29, "....." },
  [86576] = { "Ninnoli delle Furie Rosse", "Porta $N1 Glittering Sunstone a Mor'rogal.", "Oltre a spargere la loro sporcizia per tutta la ⟦Charred Vale=Valle Bruciata⟧, le arpie delle Furie Rosse raccolgono qualsiasi cosa luccicante riescano a trovare. Mi dicono che collezionano diverse pietre solari giallo oro come decorazione. Io non so che farmene di questi ninnoli, ma Mor'rogal ha detto di averle usate in passato.\n\nMentre combatti le arpie della valle, tieni gli occhi aperti per le Glittering Sunstone. Porta quelle che trovi a Mor'rogal, sulle colline sopra di noi.", "Ho questioni importanti da considerare, {class}. Sii rapido.", "Ah, hai portato le pietrasole che raccolgono le arpie! Alle arpie piace accumulare oggetti luccicanti, ma non conoscono il vero valore di queste pietre. Catturando la luce abbagliante del sole, queste pietre ne riflettono la maestà e ci permettono di adornare i nostri santuari e le nostre case con minuscole scintille di luce in suo onore. Anche la luna le illumina con la sua bellezza argentea durante la notte.\n\nQueste pietre ci ricordano il legame che abbiamo con le luci dei cieli.", 0x8c0d1828, 0x3c6482c9, 0x2a34d371, 0x6ed02622, 0xec32fdc4, "....." },
  [86577] = { "Un campione di putrescenza", "Porta $N1 Organi d'Orso Putrescenti e $N2 Organi di Lupo Putrescenti a ⟦Kelek Skykeeper=Guardiacielo Kelek⟧.", "La corruzione che piove da Hyjal scorre nelle acque della montagna e si infiltra in tutto ciò che vive qui nel bosco. Le creature che bevono quell'acqua assorbono la corruzione. Le rende feroci, malate e senza paura.\n\nPer contrastare questi effetti devo comprenderli, e per farlo mi servono campioni dagli afflitti.\n\nUn po' di organi putrescenti di lupi e orsi dovrebbero bastare. Prenditi il tempo che ti serve: queste creature sono comuni qui a ⟦Felwood=Vilbosco⟧.", nil, nil, 0xfedf93d7, 0xd851b48c, 0x23067a2e, nil, nil, "...mm" },
  [86585] = { "Lo stendardo della caduta", "Issa lo stendardo di ⟦Ironforge=Forgiardente⟧, richiama il trogg Headsplitter e uccidilo, poi fai rapporto al capitano Granchiasso.", "La montanara caduta porta uno stendardo di ⟦Ironforge=Forgiardente⟧. Forse era in perlustrazione, o forse stava guidando una carica disperata. In ogni caso, lo stendardo è stato gettato a terra e calpestato. La montanara è stata colpita alla testa così forte da perdere l'elmo, ed è stata uccisa sul colpo da un trogg, probabilmente con una clava chiodata.\n\nIl trogg che l'ha uccisa è forse ancora nei paraggi, e di certo ricorda lo stendardo. Issare di nuovo lo stendardo di ⟦Ironforge=Forgiardente⟧ potrebbe attirarlo allo scoperto.", "Quello stendardo sembra reduce da una guerra!", "Hai trovato il corpo di Ylva? Ah, povera donna. Diceva che avrebbe dimostrato ai trogg che ⟦Ironforge=Forgiardente⟧ non sarebbe mai caduta per mano della loro razza. Era andata a cercare alcuni montanari mai tornati da una pattuglia nel territorio dei trogg. Era sempre stata troppo indipendente per essere prudente. Ora sappiamo cos'è successo.\n\nRiporterò indietro lo stendardo e mi assicurerò che venga ripulito ed esposto. Tu prendi la sua arma. Che possa servirti bene contro i trogg.", 0xe9fba8e6, 0x55701efb, 0x9ae4d6b9, 0xe66f0ce2, 0x0c4098ad, "....." },
  [86611] = { "Ninnolo del Signore dei Cervi", "Porta il Ninnolo del Signore dei Cervi a qualcuno nella ⟦Talonbranch Glade=Radura di Ramocurvo⟧ che potrebbe saperne qualcosa.", "<La pozza di melma fetida ha eroso la statua del cervo. Non è chiaro come sia finita qui, sul fondo del lago.\n\nUn singolo cristallo incastonato in un medaglione intorno al suo collo emette un riflesso verde e malsano. Vale la pena portarlo a qualcuno che possa conoscere la storia di questo monumento.>", nil, nil, 0x64f22cb2, 0xe8046376, 0x228be591, nil, nil, "...mm" },
  [86612] = { "Ninnolo del Signore dei Cervi", "Porta il Ninnolo del Signore dei Cervi a qualcuno all'⟦Bloodvenom Post=Accampamento di Sanguemarcio⟧ che potrebbe saperne qualcosa.", "<La pozza di melma fetida ha eroso la statua del cervo. Non è chiaro come sia finita qui, sul fondo del lago.\n\nUn singolo cristallo incastonato in un medaglione intorno al suo collo emette un riflesso verde e malsano. Vale la pena portarlo a qualcuno che possa conoscere la storia di questo monumento.>", nil, nil, 0x64f22cb2, 0xa5862f00, 0x228be591, nil, nil, "...mm" },
  [86613] = { "Attrezzi da scavo", "Riporta $N1 ⟦Excavation Tools=Attrezzi da Scavo⟧ a ⟦Magmar Fellhew=Magmar Viltaglio⟧.", "Gli attrezzi dello scavo, abbandonati quando i nani sono fuggiti dai trogg, sembrano per lo più intatti. Riportarli agli scavatori aiuterà di certo il loro lavoro.", "Dobbiamo solo, ehm, spostare il nostro sito di scavo e potremo rimettere tutto in carreggiata!", "I nostri attrezzi!\n\nQuando i trogg hanno invaso l'accampamento, abbiamo dovuto lasciare indietro la maggior parte dei nostri attrezzi. Sarà di grande aiuto quando avremo questa invasione sotto controllo e potremo ricominciare a lavorare!", 0x417702d1, 0x4b1ae3e2, 0xf80c3305, 0x5a718cf3, 0x5c97d609, "....." },
  [86614] = { "Argento delle onde", "Restituisci il fermaglio per capelli d'argento con il monogramma a chi lo ha perso.", "<Tra le cianfrusaglie da pesca sparse fra i detriti ci sono alcuni ami arrugginiti, bobine di filo rotte e un fermaglio per capelli d'argento, un po' corroso ma finemente lavorato, con il monogramma \"K.D.\">", "Ho un sacco di faccende da sbrigare oggi, puoi fare in fretta?", "Il mio fermaglio! Pensavo di averlo perso per sempre!\n\nCon un po' di lavoro tornerà a splendere. Grazie per avermelo portato! Ti ricompenserò come si deve.", 0x90b2445c, 0x1d2fd811, 0xbaa09a33, 0x46c58e1a, 0x873f10f3, "....." },
  [86615] = { "Obblighi del trattato", "Trova la valigetta diplomatica scomparsa dell'ambasciatore Pietrarossa al ⟦Wildhammer Keep=Forte dei Granmartello⟧.", "Ach! Eccomi qui a fare l'ambasciatore presso i Granmartello e ho lasciato la mia borsa con gli ultimi dispacci diplomatici da qualche parte nel ⟦Wildhammer Keep=Forte dei Granmartello⟧. Devo averla lasciata nella taverna... o forse l'ho smarrita vicino ai carri a vapore... o era di sopra? Non riesco mai a tenere il conto!\n\nMi servono quei documenti! Se hai l'occhio più allenato del mio per il forte, vedi se riesci a individuare la mia borsa diplomatica scomparsa!", "Mi servono quei documenti!", "L'hai trovato! Fammi solo controllare che ci sia tutto... in diplomazia non si è mai troppo prudenti!\n\nSembra che non manchi nulla. Sarebbe potuto diventare un grave incidente diplomatico! Grazie per l'aiuto, {class}.", 0xfe6a2053, 0x0e2ffe00, 0x49bb9f55, 0xee4927bc, 0x9b470d0f, "....." },
  [86616] = { "Totem riadattati", "Riporta $N1 Totem dei Ramovile a Maret Curafuoco.", "Per uno sciamano, una delle difficoltà della comunione con gli elementi è che ci sono altri sciamani con intenzioni opposte. Agli elementi non importa perché facciamo ciò che facciamo, fanno solo ciò che chiediamo!\n\nAnche i troll di Jintha'alor praticano le arti sciamaniche, e le loro interruzioni e i loro attacchi sono una spina nel fianco costante per noi qui.\n\nTrova i loro Totem dei Ramovile e portameli, così potrò annullarne i poteri. Alcuni li portano con sé, altri li piazzano come difese attorno al loro altare.", "Meno quei troll Ramovile disturbano il flusso degli elementi, più semplice sarà comunicare con gli elementali.", "Ah, eccellente. Annullerò il potere di questi totem dei Ramovile e lo restituirò alla natura. Questo libererà gli elementali, permettendo loro di aiutarci, e indebolirà il potere dei troll.\n\nOttimo lavoro, {class}.", 0xc14dbfc0, 0xb97eb9f3, 0x53fd7512, 0xfd3d9f55, 0x6db18480, "....." },
  [86620] = { "Salvataggio dei piccoli", "Raccogli $N1 Uovo di Grifone Perduto per il ⟦Gryphon Master Talonaxe=Maestro dei Grifoni Asciartiglio⟧.", "Anche se qui abbiamo una buona schiera di grifoni, in natura ci sono sempre alcune nidiate di uova in pericolo di non farcela. Un genitore grifone può perdere uno scontro contro un lupo, o ammalarsi. Senza aiuto, i piccoli non sopravvivranno mai.\n\nPer fortuna abbiamo i mezzi per allevare e proteggere i piccoli perduti come questi. Se trovi uova abbandonate in natura, portamele.", "Non spaventare i piccoli!", "Ahh, un lavoro ben fatto. Tanti piccoli hanno ora una possibilità di un futuro migliore. Daremo loro un nido caldo e tanto cibo, e diventeranno ottimi compagni.\n\nBen fatto, {class}.", 0x6f8f332b, 0x533d5825, 0x45ebd2e3, 0xaffc0e8b, 0xcbe68447, "....." },
  [86667] = { "Tra le nevi", "Consegna un ⟦Jar of Snow=Barattolo di Neve⟧ a Norric Lochthane, nella sua casa sulla costa nord-occidentale del Loch.", "Il mio vecchio mentore, Norric, mi ha mandato un elementale minore con una strana richiesta. Gli serve un barattolo di neve per certe sue pratiche sciamaniche! Non so cosa ci voglia fare, ma ho imparato da tempo a non discutere i suoi metodi in fatto di magia.\n\nSto studiando gli elementali della zona, quindi non posso andare ad aiutarlo. Va' all'ingresso della galleria al ⟦South Gate Pass=Passo Meridionale⟧, dove c'è neve tutto l'anno. Raccoglila in questo barattolo di ceramica e portagliela prima che si sciolga. Il barattolo dovrebbe tenerla al fresco.", "Eh? Che cosa vuoi?", "Questo barattolo è per me?\n\nNeve! Grenhild ce l'ha fatta! Mi ha mandato la neve che le avevo chiesto!\n\nPeccato, però: speravo che venisse a trovarmi di persona.\n\nBe', in ogni caso, grazie per il tuo impegno. È un vero aiuto per il mio lavoro.", 0x7219b30d, 0xf3253110, 0x938b1d88, 0x8793ff36, 0x36e8bcbb, "....." },
  [86746] = { "La minaccia dei Legashi", "Uccidi $N1 ⟦Legashi Satyr=Satiro Legashi⟧, $N2 Ladro Legashi e $N3 Invocatore Infernale Legashi per Ekkal alle Rovine di Eldarath.", "Il mio popolo è in difficoltà, {name}.\n\nI satiri Legashi hanno invaso la nostra tana, corrompendo molti Zannanera e separandoci dai nostri alleati Mordilegno. Chi di noi sopravvive ai loro attacchi si ammassa in accampamenti di fortuna. Peggio ancora, la corruzione dei satiri si sta diffondendo sulla terra e rappresenta una minaccia per la mia tribù già vulnerabile.\n\nI Legashi si nascondono tra le rovine a nordest di qui. Devo chiederti aiuto per sconfiggerli.", nil, nil, 0x2073c18d, 0x86f32380, 0x2ede136f, nil, nil, "...mm" },
  [86747] = { "Corni Legashi", nil, "Ti sei certamente dimostrat<o/a> degn<o/a> ai miei occhi, {name}, ma gli altri della mia tribù sono meno facili da convincere. Per questo dovrai continuare i tuoi sforzi contro i Legashi.\n\nPortami le corna dei satiri Legashi uccisi. Ogni fascio che mi porterai sarà un simbolo del tuo servizio agli Zannanera.", nil, nil, 0x46439031, nil, 0xb1c3b2ab, nil, nil, ".m.mm" },
  [86752] = { "Rapporto a Gridoatroce", "Parla con il ⟦Gatekeeper Rageroar=Custode del Portale Gridoatroce⟧ a Ursolan.", "C'è ancora molto da fare nella nostra lotta contro i satiri, {name}.\n\nSe desideri essere d'ulteriore aiuto, parla con il ⟦Gatekeeper Rageroar=Custode del Portale Gridoatroce⟧ agli accampamenti di Ursolan, a nord. Saprà dove impiegare al meglio le tue abilità. Troverai Ursolan a nord di qui.", nil, nil, 0xdada9623, 0x3ea1e944, 0xb2d23b77, nil, nil, "...mm" },
  [86757] = { "Frenare l'avanzata degli orchi", "Porta $N1 Jagged Orc Sword e $N2 Curved Orc Dagger a Shandrina.", "Gli orchi si sono impadroniti della foresta orientale, e ora i loro esploratori e i loro soldati si aggirano per tutti i boschi! Per quelli come noi non è più sicuro muoversi per ⟦Ashenvale=Valtetra⟧.\n\nDobbiamo respingere gli orchi e mettere in sicurezza la foresta. Siamo riusciti a eliminare alcuni soldati ed esploratori muovendoci con cautela lungo i margini del loro accampamento.\n\nCombatti gli orchi e portami le spade seghettate e i coltelli ricurvi che usano. Mi assicurerò che le loro armi vengano recuperate e riutilizzate, così che nulla vada sprecato.", "Temo per ciò che sarà delle nostre case se gli orchi continueranno a spingersi più a fondo nelle foreste.", "Ottimo lavoro, {name}.\n\nDeploro la situazione che ci costringe a ricorrere a questo tipo di violenza, ma se gli orchi non vengono fermati, invaderanno Astranaar e abbatteranno l'intero bosco. Almeno possiamo riutilizzare il metallo delle loro rozze armi per costruire le nostre difese.", 0xa5ae3f5b, 0xef062d38, 0xf54c066d, 0x073861b9, 0xd7b51777, "....." },
  [86758] = { "Il coltello nella piaga", "Trova e sconfiggi il crocolisco Daggerfang e riporta il coltello di Marek.", "Ti ho mai raccontato di quando per poco non ci rimettevo la mano per colpa di un crocolisco? Sono riuscito a piantargli il coltello nella mascella e me la sono filata alla svelta. Credevo di avere il coltello qui da qualche parte, ma non riesco a trovarlo.\n\nComunque, quel croco è probabilmente ancora là fuori a cacciare lungo la riva del lago. Quella bestiaccia va tolta di mezzo, se non altro per la sicurezza degli altri cacciatori.\n\nHo preso a chiamarlo Daggerfang. Se lo vedi, salutalo da parte mia! E per \"salutalo\" intendo \"infilzalo\".", "Come va la caccia?", "Ah! Ce l'hai fatta! Non avrei mai pensato che quel vecchio croco avrebbe avuto ciò che si meritava, ma così va benone!\n\nOh, ehm... sai, mi son dovuto procurare un altro coltello, ma magari quello ti porterà fortuna. Perché non te lo tieni?", 0xe00ca7df, 0x0397565f, 0x466c095b, 0x023e1b29, 0x855b32ce, "....." },
  [86776] = { "Ingredienti per la forgia", "Porta $N1 Lingotto di Bronzo a ⟦Morhan Coppertongue=Morhan Spargirame⟧.", "Thelsamar è un posto magnifico in cui vivere, ma non abbiamo tutte le comodità di ⟦Ironforge=Forgiardente⟧. Resto sempre senza bronzo! Me ne serve dell'altro, se voglio continuare a fare attrezzi, bollitori e pentole!\n\nSi vede che hai un po' di esperienza alla forgia. Pensi di potermi fondere qualche lingotto di bronzo? Ti pagherò bene!", "Le forge devono restare accese!", "Ah, che sollievo! Ora dovrei riuscire a tenere accesa la forgia. Speriamo che un giorno o l'altro arrivi un mercante a portare regolarmente il carbone in città!", 0xd4a01b9a, 0x3fc9ca9a, 0x466409ef, 0xef5d24bd, 0xde5ced06, "....." },
  [86777] = { "⟦Master Feardred=Maestro Malangoscia⟧", "Uccidi ⟦Master Feardred=Maestro Malangoscia⟧ e porta il suo amuleto a Korsa.", "Molti satiri corrompono Azshara, ma nessuno è terribile come i Legashi. Guidati da Varrox Zoccolotetro, i loro accampamenti punteggiano la penisola settentrionale. Ci hanno cacciati dalle nostre case e temo che presto saccheggeranno Ursolan.\n\nDobbiamo contrattaccare se vogliamo avere una possibilità di sopravvivere.\n\nIl ⟦Master Feardred=Maestro Malangoscia⟧, un servitore di Varrox, sovrintende a un accampamento vicino, a sud. Puoi vederlo da qui. Malangoscia è un bersaglio chiave per indebolire le forze di Varrox. Uccidilo e portami il suo amuleto.", nil, nil, 0x9f2c93c4, 0x97b4c61a, 0xf118a1c4, nil, nil, "...mm" },
  [86784] = { "Rami e ossa", "Raccogli $N1 Dry Branch e portali a Eleanor Shackleton.", "La mia collega Eleanor Shackleton va fiera di viaggiare per le terre selvagge, sopravvivendo alle intemperie e ai mostri. Al momento è accampata non lontano da qui, sulle colline a ovest, e ricordo un consiglio che mi diede una volta: \"Quando pensi di avere abbastanza legna da ardere, raccogline cinque volte tanto.\"\n\nSe hai un po' di tempo libero, potresti raccogliere della legna in questo cesto e portarla al suo accampamento. Di sicuro potrebbe darti qualche consiglio sulla vita di un avventuriero errante.", "<Benvenuto/Benvenuta> al mio fuoco, <viaggiatore/viaggiatrice>.", "Altra legna da ardere? È sempre la benvenuta. Terrà al caldo queste vecchie ossa durante le notti fredde delle Radure.\n\nIo ho già una fascia per raccogliere la legna, quindi puoi pure tenerti quel cesto.", 0x9975c906, 0x1d5e65f3, 0xbc307d2c, 0x5adb408d, 0x33ffab6b, "....." },
  [86791] = { "Esploratori Zannanera scomparsi", "Trova la squadra di esplorazione degli Zannanera vicino agli accampamenti Legashi a est di Ursolan.", "Non molto tempo fa ho mandato un gruppo di esploratori a raccogliere informazioni sulla roccaforte dei Legashi e magari a trovare il nostro capo. Non sono ancora tornati. Comincio a temere il peggio.\n\nI Legashi hanno molti accampamenti a est di qui. Se qualche membro del gruppo è ancora vivo, probabilmente si trova da qualche parte lì vicino.", nil, nil, 0xfc6f0a61, 0x7b92d355, 0x4f913a29, nil, nil, "...mm" },
  [86792] = { "Assottigliare le loro forze", "Uccidi $N1 Evocainferno Legashi, $N2 Ladro d'Anime Legashi e $N3 Guardia Nera Legashi per Korsa fuori dalla Roccaforte Legashi.", "I satiri all'interno della roccaforte dei Legashi sono ancora più temibili di quelli degli accampamenti esterni. Quando il nostro gruppo è stato scoperto, ci siamo trovati sopraffatti.\n\nUno di noi è stato ucciso e un altro catturato. Solo io ho potuto ritirarmi con successo. Non posso tornare da Gridoatroce a testa bassa per la vergogna, ma non posso nemmeno combattere i Legashi senza aiuto.\n\nTi chiedo quindi di aiutarmi a indebolire le forze dei satiri. Entra nella loro roccaforte e uccidili.", nil, nil, 0x3006e447, 0x72b75099, 0x81a0d931, nil, nil, "...mm" },
  [86796] = { "A dopo, satiro", "Aiuta Graal a fuggire dalla Roccaforte Legashi, poi informa Korsa fuori dalla Roccaforte Legashi.", "Ehi tu, {race}!\n\nQuesti demoni hanno teso un'imboscata al mio gruppo di esploratori e mi hanno fatto prigioniero. Non so che piani abbiano per me, ma non intendo scoprirlo. Devo fuggire e tornare a Ursolan; di certo Korsa è in pena per me.\n\nPur desiderando uscire da questa gabbia e lasciarmi dietro una scia di cadaveri di satiri, temo di essere leggermente in inferiorità numerica.\n\nForse condividi il mio odio per questi demoni e mi aiuteresti a fuggire?", nil, nil, 0x917ab6c1, 0x3b139131, 0xa6cc9072, nil, nil, "...mm" },
  [86797] = { "Ritorno da Gridoatroce", "Torna dal ⟦Gatekeeper Rageroar=Custode del Portale Gridoatroce⟧ a Ursolan.", "Con la roccaforte dei Legashi indebolita, possiamo tornare a Ursolan con onore.\n\nPrecedimi e informa il ⟦Gatekeeper Rageroar=Custode del Portale Gridoatroce⟧ della situazione qui.", nil, nil, 0xd0444286, 0x9a2b8840, 0x08fbf252, nil, nil, "...mm" },
  [86798] = { "Rinforzi dei Mordilegno", "Parla con ⟦Gorn One Eye=Gorn Monocolo⟧ nel ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e chiedigli di fornire rinforzi.", "Con i satiri indeboliti, è il momento di lanciare un contrattacco. Il principe Halanox, comandante della Roccaforte Legashi, sarà il nostro bersaglio. Tuttavia, non abbiamo ancora i numeri per affrontarlo di petto.\n\nDa quando i Legashi ci hanno cacciati, siamo tagliati fuori dai mezzorsi del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧. Potremmo chiamarli come rinforzi, ma ci servirà un emissario. Quell'emissario sarai tu, {name}.\n\nVa' al ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e cerca un mezzorso di nome ⟦Gorn One Eye=Gorn Monocolo⟧. Ci fornirà i soldati di cui abbiamo bisogno.", nil, nil, 0xcff8f73c, 0x178d840b, 0x3d91a7c7, nil, nil, "...mm" },
  [86799] = { "Corruzione dilagante", "Parla con l'anziano Spezzarovi della malattia di Furze.", "<Furze emette una tosse brutta e rauca.>\n\nAscoltami, {race}, non ho molta forza per parlare. Sono colpito da una malattia diversa da qualunque io abbia mai conosciuto. È come se il mio stesso sangue fosse in fiamme e la mia stessa essenza si stesse disfacendo. A malapena riesco a muovermi, figurarsi a cercare aiuto.\n\nTi prego, vai a cercare l'anziano Spezzarovi. La sua tenda è subito a nordovest di qui. Saprà cosa fare.", nil, nil, 0x627f275e, 0xa7fad159, 0xca0fc3a4, nil, nil, "...mm" },
  [86804] = { "Una fonte improbabile", "Trova un modo per ottenere dell'Acquavite Legashi nell'Accampamento Legashi.", "Furze non è il primo con questo male. Da quando sono iniziati gli attacchi dei Legashi contro di noi, molti Zannanera si sono presentati con una malattia simile. Ognuno alla fine è caduto nella corruzione, diventando privo di senno e distruttivo.\n\nHo lavorato a una cura. I miei studi indicano che se ne potrebbe ricavare una trasmutando la stessa acquavite dei Legashi, ma non posso procurarmela da sola.\n\nPotresti trovare dell'acquavite, o un modo per prepararla, negli accampamenti dei Legashi a est. Saresti di grande aiuto se lo facessi.", nil, nil, 0x0ca7df42, 0x3c52e9a8, 0xf92b9f54, nil, nil, "...mm" },
  [86812] = { "Tintura trasmutata", "Usa la Tintura d'Erba dei Satiri su $N1 Corsiero Zoccolomuschio o Assalicieli Testatuono dopo averli indeboliti.", "Ho trasmutato l'acquavite in una tintura che credo sarà la chiave per annullare la corruzione dei Legashi. Per quanto sia ansiosa di alleviare la sofferenza degli Zannanera, va messa alla prova.\n\nHo visto molti courser e skystormer a est di Ursolan soffrire per la corruzione dei satiri. Saranno i nostri soggetti di prova.\n\nVa', e prova la mia presunta cura sulle bestie afflitte. Prima di somministrare la tintura la bestia va indebolita, per assicurarsi che possa essere somministrata con poca resistenza.", nil, nil, 0x95f2a457, 0x91c222e4, 0x1d1dca1f, nil, nil, "...mm" },
  [86813] = { "Una possibile panacea", "Somministra la Panacea di Spezzarovi a Furze.", "Devo ammetterlo, {class}. Era da un po' che non mi sentivo così ottimista. Questa tintura potrebbe essere la panacea che ci salva dalla piaga sempre più estesa dei satiri. Anche se dovessimo restare in questi accampamenti per il resto della nostra vita, resisteremo forti e liberi dalla corruzione.\n\nVa' da Furze e dagli questa panacea. Ha sofferto abbastanza. Torna da me per riferire ciò che scopri.", nil, nil, 0x0a3969d9, 0x9c6ff7d9, 0x16695db1, nil, nil, "...mm" },
  [86814] = { "Controffensiva degli Zannanera", "Pianta lo Stendardo di Guerra dei Mordilegno alla Roccaforte Legashi, in Azshara. Uccidi il principe Halanox e riferisci la tua vittoria al ⟦Gatekeeper Rageroar=Custode del Portale Gridoatroce⟧ a Ursolan.", "Manderò subito i rinforzi a Ursolan.\n\nPrendi questo stendardo. Quando sarai pront<o/a> ad affrontare Halanox, piantalo nel suo cerchio di evocazione demoniaco. Lo provocherà e segnalerà ai nostri guerrieri di colpire.\n\nQuando Halanox sarà sconfitto, informa il ⟦Gatekeeper Rageroar=Custode del Portale Gridoatroce⟧.", nil, nil, 0xe5c8f325, 0x74517799, 0x4d944136, nil, nil, "...mm" },
  [86925] = { "Fatica e travaglio", "Trova una Ricetta dell'Acquavite Legashi sui satiri nell'Accampamento Legashi.", "Pare che questo calderone possa servire a distillare l'acquavite che l'anziano Spezzarovi cerca.\n\nSe solo sapessi come. Di certo uno dei satiri dell'Accampamento Legashi deve avere con sé una ricetta.", nil, nil, 0x038883e2, 0x9181f455, 0xdfc7d0df, nil, nil, "...mm" },
  [86926] = { "Fuoco vile arde, il calderone ribolle", "Porta $N1 Erba dei Satiri e una Particella di Vil al Calderone Legashi nell'Accampamento Legashi.", "La ricetta dice:\n\nRaccogli il germoglio dell'inferno\nun fascio da cinque ti servirà bene\nmescolato a una particella di potere demoniaco\nannuncerà la loro ora finale", nil, nil, 0xe3b11032, 0x1571c3bb, 0x0f8aa386, nil, nil, "...mm" },
  [86927] = { "Contrabbando di acquavite", "Porta l'Acquavite Legashi all'anziano Spezzarovi a Ursolan.", "Non appena l'Erba dei Satiri e la Particella di Vil finiscono nel liquido bollente, ne sale una nube di gas nocivo.\n\nMeglio tapparsi il naso, prendere in fretta un campione e riportarlo all'anziano Spezzarovi.", nil, nil, 0xf78815ba, 0xbbb8183d, 0x6809f961, nil, nil, "...mm" },
})
